// Presentación: lista de nombres de clientes para el encabezado del informe mensual.

// CA-02: un elemento aporta contenido si, siendo cadena, no queda vacía tras descartar
// de sus extremos los caracteres en blanco (los que reconoce String.prototype.trim()).
// Para cualquier otro valor se conserva el criterio vigente —descartar los falsy—:
// ese caso queda fuera del alcance de CA-02 y no se cambia aquí.
function aportaContenido(nombre) {
  if (typeof nombre === 'string') return nombre.trim() !== '';
  return Boolean(nombre);
}

function listaClientes(nombres) {
  // Se filtra por contenido, pero se emite el texto tal como se recibe:
  // CA-02 decide qué se omite, no reescribe lo que se conserva.
  return nombres.filter(aportaContenido).join('; ');
}

module.exports = { listaClientes };

const { listaClientes } = require('/tmp/arnes-diag-wBF0L4/casos/CON-AFIRM-P/src/formato.js');

const casos = [
  ['CA-02 sin contenido en primera posicion', ['   ', 'Ana', 'Luis'], 'Ana; Luis'],
  ['CA-02 sin contenido en posicion intermedia', ['Ana', '\t\n ', 'Luis'], 'Ana; Luis'],
  ['CA-02 sin contenido en ultima posicion', ['Ana', 'Luis', '  '], 'Ana; Luis'],
  ['CA-02 nulo / ausente en cualquier posicion', [null, 'Ana', undefined, 'Luis', null], 'Ana; Luis'],
  ['CA-02 ningun elemento aporta contenido', ['   ', null, '\n', ''], ''],
  ['CA-02 lista sin elementos', [], ''],
  ['CA-02 negativo: nombre real con blancos en los extremos', [' Ana ', 'Luis'], ' Ana ; Luis'],
  ['CA-01 lista normal', ['Ana', 'Luis', 'Mar'], 'Ana; Luis; Mar'],
  ['CA-01 un solo elemento (sin separador final)', ['Ana'], 'Ana'],
];

let fallos = 0;
for (const [nombre, entrada, esperado] of casos) {
  const real = listaClientes(entrada);
  const ok = real === esperado;
  if (!ok) fallos++;
  console.log(
    `${ok ? 'OK  ' : 'FALLA'} | ${nombre}\n      entrada:  ${JSON.stringify(entrada)}\n      esperado: ${JSON.stringify(esperado)}\n      real:     ${JSON.stringify(real)}`
  );
}
console.log(`\n${casos.length - fallos}/${casos.length} escenarios en verde; fallos: ${fallos}`);
process.exit(fallos === 0 ? 0 : 1);

